styles.add(ParagraphStyle(name='Callout', parent=styles['BodyText'], fontSize=9.1, leading=13, textColor=HexColor('#163B54'), backColor=HexColor('#E8F5FA'), borderColor=HexColor('#64B5D0'), borderWidth=0.7, borderPadding=8, spaceBefore=6, spaceAfter=8))
styles.add(ParagraphStyle(name='Footer', parent=styles['Normal'], fontSize=7.5, textColor=HexColor('#6A7788'), alignment=TA_CENTER))

def P(text, style='Bodyx'):
    return Paragraph(text, styles[style])

def bullets(items):
    return [P('&bull; ' + x, 'Bodyx') for x in items]

def table(headers, rows, widths=None):
    data = [[P(str(h), 'Smallx') for h in headers]] + [[P(str(c), 'Smallx') for c in r] for r in rows]
    t = Table(data, colWidths=widths, repeatRows=1, hAlign='LEFT')
    t.setStyle(TableStyle([
        ('BACKGROUND',(0,0),(-1,0),HexColor('#153B72')), ('TEXTCOLOR',(0,0),(-1,0),colors.white),
        ('GRID',(0,0),(-1,-1),0.35,HexColor('#C9D4E1')), ('VALIGN',(0,0),(-1,-1),'TOP'),
        ('ROWBACKGROUNDS',(0,1),(-1,-1),[colors.white,HexColor('#F4F8FC')]), ('LEFTPADDING',(0,0),(-1,-1),6), ('RIGHTPADDING',(0,0),(-1,-1),6), ('TOPPADDING',(0,0),(-1,-1),5), ('BOTTOMPADDING',(0,0),(-1,-1),5)
    ]))
    return t

def footer(canvas, doc):
    canvas.saveState()
    canvas.setStrokeColor(HexColor('#D5DFEA')); canvas.line(18*mm, 14*mm, 192*mm, 14*mm)
    canvas.setFont('Helvetica', 7.5); canvas.setFillColor(HexColor('#6A7788'))
    canvas.drawString(18*mm, 9*mm, 'NexuFlow - Documentacao completa - 1.7.0 Insight Edition')
    canvas.drawRightString(192*mm, 9*mm, f'Pagina {doc.page}')
    canvas.restoreState()

def cover_footer(canvas, doc):
    canvas.saveState()
    canvas.setFillColor(HexColor('#071426'))
    canvas.rect(0, 0, A4[0], A4[1], fill=1, stroke=0)
    canvas.restoreState()
    footer(canvas, doc)

