story += [P('3. Sistema de ping e qualidade de rede', 'H1x'), P('O NexuFlow nao confunde um unico ping com a experiencia inteira. A janela de qualidade agrega latencia, jitter, perda de pacotes, picos, disponibilidade e um Nexus Score de 0 a 100. Perda recebe peso maior que pequenas diferencas de latencia.', 'Bodyx'), P('Monitor ao vivo', 'H2x'), *bullets(['Amostragem local aproximadamente a 1 Hz, sem interceptacao por pacote.', 'Janela de ate dois minutos, com mediana, minimo, maximo, p95, jitter e picos.', 'Timeouts e lacunas permanecem como ausencia de dado; nao sao convertidos em 0 ms.', 'Apos cinco segundos sem amostra, a leitura atual fica stale/desconhecida.', 'Quando a referencia muda, o grafico inicia um novo segmento para nao misturar destinos.']), P('Scanner neutro', 'H2x'), table(['Parametro','Comportamento'],[('Destinos','1.1.1.1, 8.8.8.8 e 9.9.9.9; lista fixa, sem alvo arbitrario.'),('Carga','12 sondas por destino, paralelas em grupos de 3; maximo de 36 consultas.'),('Timeout/intervalo','600 ms por sonda e 250 ms entre consultas.'),('Windows','ICMP nativo.'),('Outros sistemas','Fallback TCP/443, informado no resultado.'),('Conclusao','Referencias estaveis, divergencia, oscilacao compartilhada ou nenhuma resposta; nao culpa automaticamente o provedor.')], [38*mm,132*mm]), P('Importante: esse scanner mede a qualidade de referencias gerais da Internet. Ele nao le sockets do jogo e nao afirma ser o ping exato do servidor da partida.', 'Callout')]
